import"./page_favicon.js";import"./history_clusters_shared_style.css.js";import"chrome://resources/cr_elements/cr_action_menu/cr_action_menu.js";import"chrome://resources/cr_elements/cr_icon_button/cr_icon_button.js";import"chrome://resources/cr_elements/cr_lazy_render/cr_lazy_render.js";import{I18nMixin}from"chrome://resources/cr_elements/i18n_mixin.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{PolymerElement}from"chrome://resources/polymer/v3_0/polymer/polymer_bundled.min.js";import{BrowserProxyImpl}from"./browser_proxy.js";import{Annotation}from"./history_cluster_types.mojom-webui.js";import{getTemplate}from"./url_visit.html.js";import{insertHighlightedTextWithMatchesIntoElement}from"./utils.js";const annotationToStringId=new Map([[Annotation.kBookmarked,"bookmarked"]]);const ClusterMenuElementBase=I18nMixin(PolymerElement);class VisitRowElement extends ClusterMenuElementBase{static get is(){return"url-visit"}static get template(){return getTemplate()}static get properties(){return{query:String,visit:Object,fromPersistence:Boolean,annotations_:{type:Object,computed:"computeAnnotations_(visit)"},allowDeletingHistory_:{type:Boolean,value:()=>loadTimeData.getBoolean("allowDeletingHistory")},debugInfo_:{type:String,computed:"computeDebugInfo_(visit)"},inSidePanel_:{type:Boolean,value:()=>loadTimeData.getBoolean("inSidePanel"),reflectToAttribute:true},unusedTitle_:{type:String,computed:"computeTitle_(visit)"},unusedUrlForDisplay_:{type:String,computed:"computeUrlForDisplay_(visit)"}}}onAuxClick_(){this.dispatchEvent(new CustomEvent("visit-clicked",{bubbles:true,composed:true,detail:this.visit}))}onClick_(event){if(event.defaultPrevented){return}event.preventDefault();this.onAuxClick_();this.openUrl_(event)}onContextMenu_(event){if(!loadTimeData.getBoolean("inSidePanel")){return}BrowserProxyImpl.getInstance().handler.showContextMenuForURL(this.visit.normalizedUrl,{x:event.clientX,y:event.clientY})}onKeydown_(e){if(e.key!=="Enter"){return}this.onAuxClick_();this.openUrl_(e)}onActionMenuButtonClick_(event){this.$.actionMenu.get().showAt(this.$.actionMenuButton);event.preventDefault()}onHideSelfButtonClick_(event){this.emitMenuButtonClick_(event,"hide-visit")}onRemoveSelfButtonClick_(event){this.emitMenuButtonClick_(event,"remove-visit")}emitMenuButtonClick_(event,emitEventName){event.preventDefault();this.dispatchEvent(new CustomEvent(emitEventName,{bubbles:true,composed:true,detail:this.visit}));this.$.actionMenu.get().close()}computeAnnotations_(_visit){if(this.inSidePanel_){return[]}return this.visit.annotations.map((annotation=>annotationToStringId.get(annotation))).filter((id=>!!id)).map((id=>loadTimeData.getString(id)))}computeDebugInfo_(_visit){if(!loadTimeData.getBoolean("isHistoryClustersDebug")){return""}return JSON.stringify(this.visit.debugInfo)}computeTitle_(_visit){insertHighlightedTextWithMatchesIntoElement(this.$.title,this.visit.pageTitle,this.visit.titleMatchPositions);return this.visit.pageTitle}computeUrlForDisplay_(_visit){insertHighlightedTextWithMatchesIntoElement(this.$.url,this.visit.urlForDisplay,this.visit.urlForDisplayMatchPositions);return this.visit.urlForDisplay}openUrl_(event){BrowserProxyImpl.getInstance().handler.openHistoryCluster(this.visit.normalizedUrl,{middleButton:event.button===1,altKey:event.altKey,ctrlKey:event.ctrlKey,metaKey:event.metaKey,shiftKey:event.shiftKey})}}customElements.define(VisitRowElement.is,VisitRowElement);